def validate_signup(form, errors=None):
    """Return the list of problems found in a signup form (empty when the form is fine).

    Pass your own list as `errors` to collect the problems of several forms into one report.
    """
    if errors is None:
        errors = []          # a new list for every call that was not given one
    if "@" not in form.get("email", ""):
        errors.append("email must contain @")
    if len(form.get("password", "")) < 8:
        errors.append("password must have at least 8 characters")
    return errors
